const {DatabaseSync}=require('node:sqlite');const path=require('node:path');const fs=require('node:fs');
async function main(){const {pipeline,env}=await import('@huggingface/transformers');env.cacheDir=path.join(process.cwd(),'data','models');const extractor=await pipeline('feature-extraction','Xenova/multilingual-e5-small',{dtype:'q8'});const db=new DatabaseSync('data/eunistud.sqlite');db.exec('CREATE TABLE IF NOT EXISTS programme_embeddings(id TEXT PRIMARY KEY, model TEXT NOT NULL, vector TEXT NOT NULL)');const rows=db.prepare("SELECT id,content FROM programme_catalog WHERE kind='historical' AND country='Italy' AND id NOT IN (SELECT id FROM programme_embeddings WHERE model='multilingual-e5-small-q8')").all();const put=db.prepare('INSERT OR REPLACE INTO programme_embeddings VALUES(?,?,?)');for(let i=0;i<rows.length;i+=16){const batch=rows.slice(i,i+16);const texts=batch.map(row=>{const p=JSON.parse(row.content),f=p.fields;return `passage: ${f.title.value||''}. ${f.subject.value||''}. ${f.university.value||''}. ${f.degree.value||''}.`});const out=await extractor(texts,{pooling:'mean',normalize:true});db.exec('BEGIN');try{for(let j=0;j<batch.length;j++){put.run(batch[j].id,'multilingual-e5-small-q8',JSON.stringify(Array.from(out[j].data)))}db.exec('COMMIT')}catch(e){db.exec('ROLLBACK');throw e}if(i%160===0)console.log(`Indexed ${Math.min(i+16,rows.length)} of ${rows.length}`)}console.log('Index complete');db.close()};main().catch(e=>{console.error(e.message);process.exitCode=1});
